import { useEffect, useRef, useState } from 'react';
import { trpc } from '@/trpc/client';
export default function Home() {
  const hello = trpc.hello.useQuery('tRPC');
  const chatStream = trpc.chatStream.useQuery('Hello, World!');
  const [accumulated, setAccumulated] = useState('');
  const prevRef = useRef<string | undefined>(undefined);

  useEffect(() => {
    if (chatStream.data !== undefined && chatStream.data !== prevRef.current) {
      prevRef.current = chatStream.data;
      setAccumulated((prev) => prev + chatStream.data);
    }
  }, [chatStream.data]);

  return (
    <main className="p-4">
      <h1>tRPC AI Streaming Chat</h1>
      <p>Status: {hello.data ? hello.data : 'Loading...'}</p>
      <p>Stream: {chatStream.data !== undefined ? accumulated : 'Loading...'}</p>
    </main>
  );
}

